sys_script_include.script:
var getweatherinfo = Class.create();
getweatherinfo.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getInfo: function(cityName) {
		var city = cityName ? cityName : this.getParameter('sysparm_city');
		return "weather seems normal at " + city;
        //return "weather seem normal " + this.getParameter("sysparm_city") + this.getParameter("sysparm_cont");
    },


    getCallerDetails: function() {
        var callerId = this.getParameter('sysparm_caller_id');
        var result = {};

        var gr = new GlideRecord('sys_user');
        if (gr.get(callerId)) {
            //result.manager = gr.getValue('manager');
            result.manager = gr.manager.getDisplayValue();
            result.title = gr.getValue('title');
        }

        return JSON.stringify(result);
    },


    type: 'getweatherinfo'
});
